#nullable enable
using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using Unity.Entities;using Unity.Collections;using Il2CppInterop.Runtime;using Game.SpawnPointSystem;using Game.ItemsSystem.Components;using Game.ExitZoneSystem;using Game.SceneObjectsSystem;using Game.TriggerZoneSystem;
namespace Frontier.Reserve;
internal sealed class NativePlacements:IDisposable {
 readonly World world;readonly NativeBuildBarrier gate;readonly BlobAssetStore blobs;readonly LeaseBag roots=new();readonly List<Entity> owned=new();readonly Dictionary<string,WayPointAuthoring> waypoints=new();readonly GameObject root;bool disposed;internal int Converted=>owned.Count;
 internal NativePlacements(World world,NativeBuildBarrier gate,bool server){this.world=world;this.gate=gate;gate.Check();blobs=new BlobAssetStore();roots.Keep(blobs);root=new GameObject("Reserve.Points."+(server?"Server":"Client"));root.SetActive(false);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,Loader.Scene);var before=Entities(world.EntityManager);
 try{
  if(server){foreach(var a in Content.Map.Anchors.Where(a=>a.Kind=="patrol")){var go=Create(a);var wp=go.AddComponent<WayPointAuthoring>();wp._viewPoints=new Il2CppSystem.Collections.Generic.List<Transform>();wp._isStopPoint=true;wp._stopDuration=2;wp._isSpawnPoint=false;wp._useSpline=false;wp._useAutoTangent=false;wp._localTangent=Vector3.zero;waypoints[a.Id]=wp;}
   foreach(var room in Content.Map.Rooms){var p=Content.Map.Anchors.Where(a=>a.Kind=="patrol"&&a.Room==room.Id).ToArray();for(int i=0;i<p.Length;i++){var wp=waypoints[p[i].Id];wp._previousPoint=i>0?waypoints[p[i-1].Id]:null;wp._nextPoint=i+1<p.Length?waypoints[p[i+1].Id]:null;}}
  }
  foreach(var a in Content.Map.Anchors.Where(a=>a.Kind!="patrol"&&(server||a.Kind=="exit"))){var go=Create(a);
   if(a.Kind=="player"||a.Kind=="enemy"){
    var sp=go.AddComponent<SpawnPointAuthoring>();sp._areaName="Reserve/"+a.Room;sp._textDescription=a.Id;sp._index=(uint)Identity.Ordinal(a,Content.Map);sp._spawnPointId=Identity.Ordinal(a,Content.Map);sp._objectType=a.Kind=="player"?SpawnPoint.Type.Player:SpawnPoint.Type.BotPlayer;sp._sceneObjectStringId=Identity.Id(a.Id).ToString();sp._sceneObjectId=Identity.Id(a.Id);sp._setMinLevel=false;sp._setMaxLevel=false;sp._forDemonstration=false;sp._forPerformanceTest=false;sp._allowPatrolWayPointsRandomly=false;sp._patrolTraversalCount=1;
    var info=new SpawnPointAuthoring.AISpawnPointInfo{FirstSpawnDelayInSeconds=0,SpawnPauseInSeconds=3600,KeepBotAlive=false,ApplyIdleStateForFirstSpawnOnly=true,OverrideAiSettings=false,OverrideIntroBehavior=false,_spawnHandingItemTemplateId=Core.Utils.UniqueId.Empty.ToString(),_introBehaviorId=Core.Utils.UniqueId.Empty.ToString(),_aiSettingsId=Core.Utils.UniqueId.Empty.ToString()};info.OnAfterDeserialize();sp._spawnPointInfo=info;sp.OnAfterDeserialize();if(sp.GetSceneObjectId()!=Identity.Id(a.Id))throw new InvalidOperationException("Spawn authoring identity mismatch: "+a.Id);
    if(a.Kind=="enemy"){var first=Content.Map.Anchors.FirstOrDefault(p=>p.Kind=="patrol"&&p.Room==a.Room);if(first!=null)sp._wayPointSource=waypoints[first.Id];}
   }else if(a.Kind=="loot"){
    Identify(go,a);var p=go.AddComponent<ItemSpawnPointAuthoring>();p._isLegacy=false;p._areaName="Reserve/"+a.Room;p._textDescription=a.Id;p._spawnPointType=ItemSpawnPointAuthoring.SpawnPointTypes.Container;p._visualSize=ItemSpawnPointAuthoring.VisualSizes.Medium;p._containerTemplateId=LootProfiles.For(a).Template.ToString();p._templateId=LootProfiles.For(a).Template.ToString();p._mainItemAutoRespawn=false;p.IsInsideGroup=true;p._overrideInteractionCollider=true;p._overrideInteractionColliderCenter=new Vector3(0,.45f,0);p._overrideInteractionColliderSize=new Vector3(1.2f,.9f,1.2f);if(p.GetSceneObjectId()!=Identity.Id(a.Id))throw new InvalidOperationException("Loot authoring identity mismatch: "+a.Id);
   }else if(a.Kind=="exit"){
    Identify(go,a);var zone=go.AddComponent<TriggerZoneAuthoring>();zone._id=Identity.Ordinal(a,Content.Map);zone._generateEvents=true;zone._boxCenter=new Vector3(0,1.4f,0);zone._boxSize=new Vector3(5,2.8f,5);zone._collidesWith=uint.MaxValue;zone._checkStaticWorld=false;zone._triggerWithinRadius=false;
    var p=go.AddComponent<ExitZoneAuthoring>();p._templateId=Repositories.ExitTemplate.ToString();p._mainExit=true;p._activationType=ExitZoneAuthoring.ActivationType.InstantlyActive;p._index=Identity.Ordinal(a,Content.Map);p._setExitZoneId=true;p._exitZoneId=Identity.Ordinal(a,Content.Map);p._setMinLevel=false;p._setMaxLevel=false;p._carriedItemsFilter=null;p._equippedItemsFilter=null;p._forDemonstration=false;
   }
  }
  root.SetActive(true);var settings=GameObjectConversionSettings.FromWorld(world,blobs);roots.Keep(settings);settings.DebugConversionName="Frontier Reserve "+(server?"server":"client");GameObjectConversionUtility.ConvertGameObjectHierarchy(root,settings);
  foreach(var e in Entities(world.EntityManager))if(!before.Contains(e))owned.Add(e);
  Trace.Data[server?"serverPlacementValidated":"clientPlacementValidated"]=false;Trace.Data[server?"serverPlacementConversion":"clientPlacementConversion"]=new{entities=owned.Count,spawns=Count<SpawnPoint>(),enemies=Count<Game.AISystem.AIPlayerSpawnPoint>(),loot=Count<ItemSpawnPoint>(),exits=Count<ExitZone>(),triggers=Count<Game.TriggerZoneSystem.TriggerZone>(),sourceHash=Identity.Hash};Validate(server);ValidateIdentity(server);Trace.Data[server?"serverPlacementValidated":"clientPlacementValidated"]=true;
 }catch{foreach(var e in Entities(world.EntityManager))if(!before.Contains(e)&&!owned.Contains(e))owned.Add(e);Dispose();throw;}}
 GameObject Create(Anchor a){var go=new GameObject(a.Id);go.transform.SetParent(root.transform,false);go.transform.localPosition=new Vector3(a.Position[0],a.Position[1],a.Position[2]);return go;}
 static void Identify(GameObject go,Anchor a){var id=go.AddComponent<SceneObjectAuthoring>();id._isNetworkObject=true;id._stringId=Identity.Id(a.Id).ToString();id.OnAfterDeserialize();id.SetUniqueId(Identity.Id(a.Id));if(id.Id!=Identity.Id(a.Id))throw new InvalidOperationException("Scene placement identity mismatch");}
 static HashSet<Entity> Entities(EntityManager em){var set=new HashSet<Entity>();var a=em.GetAllEntities(Allocator.Temp);try{if(a.Length>200000)throw new InvalidOperationException("Unexpected world entity budget");for(int i=0;i<a.Length;i++)set.Add(a[i]);return set;}finally{a.Dispose();}}
 internal int Count<T>(){var type=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<T>()));return owned.Count(e=>world.EntityManager.Exists(e)&&world.EntityManager.HasComponent(e,type));}
 void Validate(bool server){if(Count<ExitZone>()!=2||Count<Game.TriggerZoneSystem.TriggerZone>()!=2)throw new InvalidOperationException("Native exit/trigger conversion count mismatch");if(server&&(Count<SpawnPoint>()!=4||Count<Game.AISystem.AIPlayerSpawnPoint>()!=18||Count<ItemSpawnPoint>()!=24))throw new InvalidOperationException("Native player/bot/loot conversion count mismatch: spawns="+Count<SpawnPoint>()+" bots="+Count<Game.AISystem.AIPlayerSpawnPoint>()+" loot="+Count<ItemSpawnPoint>());var disabled=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<Disabled>()));if(owned.Any(e=>world.EntityManager.HasComponent(e,disabled)))throw new InvalidOperationException("Converted placements are disabled");}
 void ValidateIdentity(bool server){var em=world.EntityManager;var spawnType=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<SpawnPoint>()));var lootType=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<ItemSpawnPoint>()));var exitType=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<ExitZone>()));var botType=ComponentType.ReadOnly(TypeManager.GetTypeIndex(Il2CppType.Of<Game.AISystem.AIPlayerSpawnPoint>()));var playerIds=new HashSet<int>(Content.Map.Anchors.Where(a=>a.Kind=="player").Select(a=>Identity.Ordinal(a,Content.Map)));var botIds=new HashSet<Core.Utils.UniqueId>(Content.Map.Anchors.Where(a=>a.Kind=="enemy").Select(a=>Identity.Id(a.Id)));var lootIds=new HashSet<Core.Utils.UniqueId>(Content.Map.Anchors.Where(a=>a.Kind=="loot").Select(a=>Identity.Id(a.Id)));var exitIds=new HashSet<int>(Content.Map.Anchors.Where(a=>a.Kind=="exit").Select(a=>Identity.Ordinal(a,Content.Map)));
 foreach(var e in owned){if(server&&em.HasComponent(e,spawnType)){var p=em.GetComponentData<SpawnPoint>(e);if(p.ObjectType!=SpawnPoint.Type.Player||!playerIds.Remove(p.SpawnPointId))throw new InvalidOperationException("Converted player point ID mismatch");}if(server&&em.HasComponent(e,botType)){var p=em.GetComponentData<Game.AISystem.AIPlayerSpawnPoint>(e);if(!botIds.Remove(p.BotSpawnPointId))throw new InvalidOperationException("Converted AI point ID mismatch");}if(server&&em.HasComponent(e,lootType)){var p=em.GetComponentData<ItemSpawnPoint>(e);if(!lootIds.Remove(p.ItemSpawnPointId))throw new InvalidOperationException("Converted loot point ID mismatch");}if(em.HasComponent(e,exitType)){var p=em.GetComponentData<ExitZone>(e);if(!exitIds.Remove(p.ExitZoneId)||p.TemplateId!=Repositories.ExitTemplate)throw new InvalidOperationException("Converted exit identity mismatch");}}
 if(exitIds.Count>0||(server&&(playerIds.Count>0||botIds.Count>0||lootIds.Count>0)))throw new InvalidOperationException("Incomplete native point ID bindings");}
 public void Dispose(){if(disposed)return;gate.Check();if(!world.WasCollected&&world.IsCreated){var em=world.EntityManager;foreach(var e in owned)if(em.Exists(e))em.DestroyEntity(e);}owned.Clear();if(root!=null)UnityEngine.Object.Destroy(root);blobs.Dispose();roots.Dispose();disposed=true;}
}
